<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-3"><div><h1 class="h3">Vendedores</h1><p class="text-secondary">Registro y asignaciones a tus campañas.</p></div><div class="d-flex flex-wrap gap-2"><a class="btn btn-outline-primary" href="index.php?c=vendedor&a=registrar">+ Registrar vendedor</a><a class="btn btn-primary" href="index.php?c=vendedor&a=asignar">+ Asignar a campaña</a></div></div><div class="row g-3"><div class="col-xl-5"><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Vendedor disponible</th><th>Mis campañas</th></tr></thead><tbody><?php foreach($vendedores as $v):?><tr><td><strong><?=e($v['nombre'])?></strong><small class="d-block text-secondary"><?=e($v['email'])?></small></td><td><?=e($v['campanias'])?></td></tr><?php endforeach;?><?php if(!$vendedores):?><tr><td colspan="2">Sin vendedores disponibles.</td></tr><?php endif;?></tbody></table></div></div></div><div class="col-xl-7"><div class="card"><div class="card-header bg-white">Asignaciones de mis campañas</div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Vendedor / campaña</th><th>Estado</th><th>Motivo y acción</th></tr></thead><tbody><?php foreach($asignaciones as $a):?><tr><td><?=e($a['vendedor'])?><small class="d-block text-secondary"><?=e($a['campania'])?></small></td><td><?=e($a['estado'])?></td><td><form method="post" action="index.php?c=vendedor&a=estado" class="d-grid gap-2"><input type="hidden" name="id" value="<?=e($a['id'])?>"><select class="form-select form-select-sm" name="estado"><option value="ACTIVO" <?=$a['estado']==='ACTIVO'?'selected':''?>>Activo</option><option value="INACTIVO" <?=$a['estado']==='INACTIVO'?'selected':''?>>Inactivo</option><option value="PENDIENTE" <?=$a['estado']==='PENDIENTE'?'selected':''?>>Pendiente</option></select><input class="form-control form-control-sm" name="observaciones" value="<?=e($a['observaciones']??'')?>" placeholder="Motivo (obligatorio si no está activo)"><button class="btn btn-sm btn-outline-primary">Guardar</button></form></td></tr><?php endforeach;?><?php if(!$asignaciones):?><tr><td colspan="3">Sin asignaciones.</td></tr><?php endif;?></tbody></table></div></div></div></div></main><?php require __DIR__.'/../footer.php';?>